		t.Fatalf("register: %v", err)
	}
	for _, task := range []Task{
		{ID: "report", Workflow: "other", DependsOn: []string{}, MaxRetries: 2},
		{ID: "report", Workflow: "nightly", DependsOn: []string{}, MaxRetries: 1},
